  node_lists {
    cvm_ips {
      ipv4s {
        value = local.cvmIp
      }
    }
    hypervisor_ips {
      ipv4s {
        value = nutanix_clustersdiscoverunconfigurednodesv2.cluster-node.unconfigured_nodes[0].hypervisor_ips[0].ipv4s[0].value
      }
    }
  }
}
