      shouldSkipAddNode: false
      shouldSkipPreExpandChecks: false
      nodeParams:
        - shouldSkipHostNetworking: false
          hypervisorIsos:
            - type: ${["cluster-node"].unconfiguredNodes[0].hypervisorType}
          nodeLists:
            - nodeUuid: ${["cluster-node"].unconfiguredNodes[0].nodeUuid}
              model: ${["cluster-node"].unconfiguredNodes[0].rackableUnitModel}
              blockId: ${["cluster-node"].unconfiguredNodes[0].rackableUnitSerial}
              hypervisorType: ${["cluster-node"].unconfiguredNodes[0].hypervisorType}
              hypervisorVersion: ${["cluster-node"].unconfiguredNodes[0].hypervisorVersion}
              nodePosition: ${["cluster-node"].unconfiguredNodes[0].nodePosition}
              nosVersion: ${["cluster-node"].unconfiguredNodes[0].nosVersion}
              hypervisorHostname: example
              currentNetworkInterface: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[0].name}
              hypervisorIps:
                - ipv4s:
                    - value: ${["cluster-node"].unconfiguredNodes[0].hypervisorIps[0].ipv4s[0].value}
              cvmIps:
                - ipv4s:
                    - value: ${cvmIp}
              ipmiIps:
                - ipv4s:
                    - value: ${["cluster-node"].unconfiguredNodes[0].ipmiIps[0].ipv4s[0].value}
              isRoboMixedHypervisor: true
              networks:
                - name: ${["node-network-info"].nodesNetworkingDetails[0].networkInfos[0].hcis[0].name}
                  networks: ${["node-network-info"].nodesNetworkingDetails[0].networkInfos[0].hcis[0].networks}
                  uplinks:
                    - actives:
                        - name: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[0].name}
                          mac: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[0].mac}
                          value: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[0].name}
                      standbies:
                        - name: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[1].name}
                          mac: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[1].mac}
                          value: ${["node-network-info"].nodesNetworkingDetails[0].uplinks[0].uplinkLists[1].name}
      configParams:
        - shouldSkipImaging: true
